pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _accessControl, uint64 _initializerVersion) public {
        // 1. Keep the access control address admissible: not zero, not the contract itself.
        vm.assume(_accessControl != address(0));
        vm.assume(_accessControl != address(c));
        // Bound the version fuzzer param to acceptable reinitializer versions (2..type(uint64).max-1).
        vm.assume(_initializerVersion >= 2 && _initializerVersion < type(uint64).max);

        // 2. Drive the reference and buggy contract through initialization.
        // We use try/catch to capture whether the call completes or reverts.
        bool referenceSuccess;
        bool mutantSuccess;

        try c.initialize(_accessControl) {
            referenceSuccess = true;
        } catch {
            referenceSuccess = false;
        }

        // Re-deploy a fresh C for the mutant behavior (C under test is the mutant).
        // Here the test file is for the mutant, but the assertion must hold for reference and fail for mutant.
        // Since the same bytecode is used, the mutant's initialize order is buggy.
        // We run the same call and observe the outcome.
        // The property is that the call succeeds and sets the access control.
        C mutant = new C();
        try mutant.initialize(_accessControl) {
            mutantSuccess = true;
        } catch {
            mutantSuccess = false;
        }

        // 3. Assert: The reference always succeeds and stores the correct accessControl (rule),
        // while the mutant can fail for some inputs. The difference is captured by whether the
        // mutant reverts when the reference does not. We assert that if reference succeeds, the
        // stored accessControl is correct, and the mutant must also succeed to satisfy the rule;
        // the fuzzer will find a case where reference succeeds but mutant fails.
        if (referenceSuccess) {
            // Reference succeeded; its accessControl getter should equal the input.
            assertTrue(c.accessControl() == _accessControl);
            // The mutant must also succeed to obey the same rule; if it fails, the property is broken.
            assertTrue(mutantSuccess);
        } else {
            // If reference failed, the input is outside admissible domain for the rule, so skip check.
            assertTrue(true);
        }
    }
}

